/**************************************************************************
 * Event handling
 */

enum ios_event_type
{
    IOS_DESKTOP_CHANGED,
    IOS_CONFIG_CHANGED,
    IOS_SURFACE_CHANGED,
    IOS_MOTION_EVENT,
    IOS_KEYBOARD_EVENT,
    IOS_HID_DEVICE_ADDED,
    IOS_HID_DEVICE_REMOVED,
    IOS_AUDIO_DEVICE_CHANGED
};

union ios_event_data
{
    enum ios_event_type type;
    struct
    {
        enum ios_event_type type;
        unsigned int    width;
        unsigned int    height;
    } desktop;
    struct
    {
        enum ios_event_type type;
        unsigned int    dpi;
    } cfg;
    struct
    {
        enum ios_event_type type;
        HWND            hwnd;
        BOOL            client;
        unsigned int    width;
        unsigned int    height;
    } surface;
    struct
    {
        enum ios_event_type type;
        HWND            hwnd;
        INPUT           input;
    } motion;
    struct
    {
        enum ios_event_type type;
        HWND            hwnd;
        UINT            lock_state;
        INPUT           input;
    } kbd;
    struct
    {
        enum ios_event_type type;
        IOS_HID_DEVICE *device;
    } hid;
    struct
    {
        enum ios_event_type type;
        IOS_AUDIO_DEVICE *device;
    } audio;
};

int ios_send_event( const union ios_event_data *data );

extern int event_source;


/**************************************************************************
 * Thread-safe event queue for main thread dispatch
 */

typedef struct _IOS_EVENT_QUEUE
{
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    union ios_event_data *events;
    int capacity;
    int head;
    int tail;
    int count;
    BOOL shutdown;
} IOS_EVENT_QUEUE;

extern IOS_EVENT_QUEUE *ios_event_queue_create( int capacity );
extern void ios_event_queue_destroy( IOS_EVENT_QUEUE *queue );
extern int ios_event_queue_push( IOS_EVENT_QUEUE *queue, const union ios_event_data *event );
extern int ios_event_queue_pop( IOS_EVENT_QUEUE *queue, union ios_event_data *event, int timeout_ms );
extern void ios_event_queue_process( IOS_EVENT_QUEUE *queue );


