/**************************************************************************
 * String conversion helpers
 */

static inline void ascii_to_unicode( WCHAR *dst, const char *src, size_t len )
{
    while (len--) *dst++ = (unsigned char)*src++;
}

static inline void unicode_to_ascii( char *dst, const WCHAR *src, size_t len )
{
    while (len--) *dst++ = (unsigned char)*src++;
}

static inline CFStringRef unicode_to_cfstring( const WCHAR *str )
{
    CFStringRef result;
    char ascii_buf[256];
    size_t len = 0;
    
    while (str[len] && len < sizeof(ascii_buf) - 1)
    {
        ascii_buf[len] = (char)str[len];
        len++;
    }
    ascii_buf[len] = 0;
    
    result = CFStringCreateWithCString( kCFAllocatorDefault, ascii_buf, kCFStringEncodingASCII );
    return result;
}


